{"tool":"execute","arguments":{"code":"vendors = {v['id']: v for v in data['vendors']}
skus = sorted(data['skus'])
options = []
for sku in skus:
    rule = data['skus'][sku]
    options.append([q for q in data['quotes'] if q['sku'] == sku and rule['demand'] <= q['units'] <= rule['demand'] + 2 and q['arrival'] <= rule['deadline'] and q['quality'] == 'approved'])
feasible = []
for choice in itertools.product(*options):
    selected = {q['sku']: q for q in choice}
    used = set(q['vendor'] for q in choice)
    if len(used) < 3 or sum(q['carbon'] for q in choice) > data['carbon_cap']:
        continue
    if any(q['needs_same_vendor_sku'] and selected[q['needs_same_vendor_sku']]['vendor'] != q['vendor'] for q in choice):
        continue
    total = 0
    valid = True
    for vendor in used:
        v = vendors[vendor]
        lots = [q for q in choice if q['vendor'] == vendor]
        units = sum(q['units'] for q in lots)
        if units > v['unit_cap']:
            valid = False
            break
        gross = sum(q['units'] * q['unit_cents'] for q in lots)
        bps = v['tier_bps'] if units >= v['tier_units'] else 0
        merchandise = (gross * (10000 - bps) + 5000) // 10000
        shipping = v['shipping_cents'] if gross < v['free_shipping_gross'] else 0
        rebate = v['rebate_cents'] if len(set(q['sku'] for q in lots)) >= 2 and merchandise >= v['rebate_merchandise_min'] else 0
        total += merchandise + shipping - rebate
    if valid:
        feasible.append(total)
answer = min(feasible)
print(FINAL(str(answer)))"}}

